cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <style>
    :root {
      --bg: #fafafa;
      --surface: #ffffff;
      --text: #171717;
      --muted: #5f6368;
      --line: #e5e7eb;
      --accent: #0072f5;
      --accent-soft: #e8f2ff;
      --shadow: 0 8px 30px rgba(10, 20, 40, 0.06);
      --radius: 14px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(1180px, 92vw);
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 30;
      background: rgba(250, 250, 250, 0.92);
      border-bottom: 1px solid var(--line);
      backdrop-filter: blur(8px);
    }

    .header-inner {
      height: 74px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 700;
      font-size: 1.05rem;
    }

    .logo {
      width: 26px;
      height: 26px;
      border-radius: 7px;
      background: linear-gradient(135deg, #0072f5 0%, #2f8dff 65%, #9bc6ff 100%);
      box-shadow: var(--shadow);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 6px;
      flex-wrap: wrap;
    }

    .nav-link,
    .menu-btn {
      border: 0;
      background: transparent;
      color: var(--text);
      font-size: 0.95rem;
      font-weight: 600;
      padding: 10px 12px;
      border-radius: 10px;
      cursor: pointer;
    }

    .nav-link:hover,
    .menu-btn:hover,
    .menu-btn[aria-expanded="true"] {
      background: #f1f5f9;
    }

    .menu-wrap { position: relative; }

    .mega {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      width: min(780px, 88vw);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: var(--surface);
      box-shadow: var(--shadow);
      padding: 20px;
      display: none;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .mega.open { display: grid; }

    .mega h4 {
      margin: 0 0 8px;
      font-size: 0.86rem;
      letter-spacing: .03em;
      text-transform: uppercase;
      color: #334155;
    }

    .mega ul { margin: 0; padding: 0; list-style: none; }
    .mega li { margin-bottom: 8px; color: #1f2937; font-size: .92rem; }

    .hero {
      padding: 42px 0 20px;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 3rem);
      line-height: 1.1;
      letter-spacing: -0.02em;
    }

    .hero p {
      max-width: 720px;
      margin: 14px 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin: 24px 0 14px;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .pill {
      border: 1px solid var(--line);
      background: #fff;
      color: #1f2937;
      border-radius: 999px;
      padding: 9px 14px;
      font-size: .9rem;
      font-weight: 600;
      cursor: pointer;
      transition: .15s ease;
      min-height: 40px;
    }

    .pill:hover { border-color: #bcd6ff; }

    .pill.active {
      background: var(--accent-soft);
      border-color: #9ec5ff;
      color: #0545a8;
    }

    .search {
      min-width: 260px;
      flex: 1;
      display: flex;
      justify-content: flex-end;
    }

    .search input {
      width: min(380px, 100%);
      border: 1px solid var(--line);
      border-radius: 12px;
      padding: 11px 14px;
      font-size: .95rem;
      outline: none;
      background: #fff;
    }

    .search input:focus { border-color: #9ec5ff; box-shadow: 0 0 0 4px #e8f2ff; }

    .section-title {
      margin: 26px 0 16px;
      font-size: 1.35rem;
      letter-spacing: -.01em;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
      margin-bottom: 24px;
    }

    .featured-card {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: #fff;
      padding: 18px;
      box-shadow: var(--shadow);
      display: flex;
      flex-direction: column;
      gap: 10px;
      min-height: 270px;
    }

    .featured-card.main {
      grid-column: span 2;
      background: linear-gradient(180deg, #ffffff, #f7fbff);
    }

    .meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      color: #475569;
      font-size: .84rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      border-radius: 999px;
      padding: 4px 10px;
      font-size: .74rem;
      font-weight: 700;
      background: var(--accent-soft);
      color: #0450be;
    }

    .featured-card h3,
    .post-card h3 {
      margin: 0;
      line-height: 1.24;
      letter-spacing: -0.01em;
    }

    .featured-card h3 { font-size: clamp(1.1rem, 2.1vw, 1.7rem); }
    .featured-card p, .post-card p { margin: 0; color: var(--muted); }

    .stats {
      margin-top: auto;
      display: grid;
      gap: 8px;
      padding-top: 8px;
      border-top: 1px dashed #bfdbfe;
    }

    .stats b { color: #0f172a; }

    .author {
      margin-top: auto;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: .88rem;
      color: #334155;
    }

    .avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      display: inline-grid;
      place-items: center;
      font-size: .75rem;
      font-weight: 700;
      background: #e2e8f0;
      color: #0f172a;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      margin-top: 8px;
    }

    .post-card {
      border: 1px solid var(--line);
      border-radius: 12px;
      background: #fff;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
      min-height: 260px;
    }

    .post-card:hover {
      transform: translateY(-2px);
      border-color: #cddcf2;
      box-shadow: var(--shadow);
    }

    .empty {
      border: 1px dashed #cbd5e1;
      border-radius: 12px;
      padding: 24px;
      background: #fff;
      text-align: center;
      color: #475569;
      display: none;
      margin-top: 10px;
    }

    .actions {
      display: flex;
      justify-content: center;
      margin: 22px 0 8px;
    }

    .btn {
      border: 1px solid #99c0ff;
      background: #fff;
      color: #0545a8;
      font-weight: 700;
      border-radius: 10px;
      padding: 11px 16px;
      cursor: pointer;
      min-height: 44px;
    }

    .btn:hover { background: #eef5ff; }

    .cta {
      margin: 34px 0;
      border-radius: 16px;
      border: 1px solid var(--line);
      background: linear-gradient(90deg, #fff, #f4f9ff);
      padding: 22px;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
    }

    .cta h3 { margin: 0; font-size: 1.25rem; }
    .cta p { margin: 6px 0 0; color: var(--muted); }

    .cta .btn {
      background: var(--accent);
      color: #fff;
      border-color: transparent;
    }

    footer {
      border-top: 1px solid var(--line);
      padding: 20px 0 34px;
      color: #475569;
      font-size: .92rem;
    }

    .foot-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
    }

    @media (max-width: 1000px) {
      .featured-grid,
      .posts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .featured-card.main { grid-column: span 2; }
    }

    @media (max-width: 760px) {
      .header-inner { height: auto; padding: 12px 0; align-items: flex-start; }
      .featured-grid,
      .posts-grid { grid-template-columns: 1fr; }
      .featured-card.main { grid-column: span 1; }
      .mega { position: fixed; left: 4vw; width: 92vw; grid-template-columns: 1fr; }
      .search { width: 100%; justify-content: flex-start; }
      .search input { width: 100%; }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <div class="brand"><span class="logo" aria-hidden="true"></span>DeployCloud Blog</div>
      <nav class="nav" aria-label="Main navigation">
        <div class="menu-wrap">
          <button class="menu-btn" id="productsBtn" aria-expanded="false" aria-controls="productsMenu">Products ▾</button>
          <div class="mega" id="productsMenu" role="menu" aria-label="Products mega menu">
            <div>
              <h4>AI Cloud</h4>
              <ul><li>AI Gateway</li><li>Sandbox</li><li>DeployCloud Agent</li><li>AI SDK</li><li>v0</li></ul>
            </div>
            <div>
              <h4>Core Platform</h4>
              <ul><li>Edge Runtime</li><li>Deployments</li><li>Observability</li><li>Storage</li><li>Build Pipeline</li></ul>
            </div>
            <div>
              <h4>Security</h4>
              <ul><li>Zero Data Retention</li><li>SSO & Access Control</li><li>Audit Logs</li><li>Threat Detection</li></ul>
            </div>
          </div>
        </div>

        <div class="menu-wrap">
          <button class="menu-btn" id="resourcesBtn" aria-expanded="false" aria-controls="resourcesMenu">Resources ▾</button>
          <div class="mega" id="resourcesMenu" role="menu" aria-label="Resources menu">
            <div>
              <h4>Company</h4>
              <ul><li>About</li><li>Careers</li><li>Press</li><li>Legal</li><li>Privacy Policy</li></ul>
            </div>
            <div>
              <h4>Learn</h4>
              <ul><li>Docs</li><li>Guides</li><li>Blog</li><li>Changelog</li><li>Status: All Systems Normal</li></ul>
            </div>
            <div>
              <h4>Open Source</h4>
              <ul><li>Open Source Program</li><li>GitHub</li><li>Events</li><li>LinkedIn</li><li>YouTube</li></ul>
            </div>
          </div>
        </div>

        <a class="nav-link" href="#latest">Latest</a>
        <a class="nav-link" href="#footer">Subscribe</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="hero">
      <h1>Discover the latest in cloud infrastructure and AI-native delivery</h1>
      <p>Engineering insights, product updates, customer stories, and community perspectives from the DeployCloud platform team.</p>

      <div class="controls" aria-label="Filters and search">
        <div class="pills" id="categoryPills" role="tablist" aria-label="Category filters"></div>
        <label class="search" for="searchInput">
          <input id="searchInput" type="search" placeholder="Search posts, topics, authors..." aria-label="Search posts" />
        </label>
      </div>
    </section>

    <section>
      <h2 class="section-title">Featured Articles</h2>
      <div class="featured-grid" id="featuredGrid"></div>
    </section>

    <section id="latest">
      <h2 class="section-title">Latest News</h2>
      <div class="posts-grid" id="postsGrid"></div>
      <div class="empty" id="noResults">No results found for this filter and search query. Try another category or clear the search.</div>
      <div class="actions"><button class="btn" id="showMoreBtn" type="button">Show more posts</button></div>
    </section>

    <section class="cta">
      <div>
        <h3>Ship your next release with DeployCloud</h3>
        <p>Build, observe, and scale with the same platform trusted by modern engineering teams.</p>
      </div>
      <button class="btn" type="button">Start deploying</button>
    </section>
  </main>

  <footer id="footer">
    <div class="container foot-row">
      <div>© 2026 DeployCloud, Inc.</div>
      <div>Built for developers · Reliable by default</div>
    </div>
  </footer>

  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        category: "Engineering",
        date: "April 20, 2026",
        title: "Agentic Infrastructure",
        excerpt: "DeployCloud now sees a structural shift in how software ships: coding agents increasingly open, iterate, and deploy with human oversight.",
        author: "Maya Chen",
        initials: "MC",
        stats: [
          "30% of deployments are now initiated by coding agents",
          "1000% increase from six months ago",
          "Teams using agents are 20 times more likely to call AI inference"
        ],
        main: true
      },
      {
        category: "Engineering",
        date: "April 12, 2026",
        title: "A new programming model for durable execution",
        excerpt: "How resumable workflows and agent checkpoints make long-running tasks reliable in production systems.",
        author: "Leon Park",
        initials: "LP"
      },
      {
        category: "Security",
        date: "April 3, 2026",
        title: "Agent responsibly",
        excerpt: "Guardrails, approvals, and observability patterns for safe autonomous coding in high-trust organizations.",
        author: "Aria Gomez",
        initials: "AG"
      }
    ];

    const allPosts = [
      { category: "Engineering", date: "April 12, 2026", title: "A new programming model for durable execution", excerpt: "Durable execution lets workflows survive restarts, retries, and handoffs across human and agent operators.", author: "Leon Park", initials: "LP" },
      { category: "Security", date: "April 8, 2026", title: "Zero Data Retention on AI Gateway", excerpt: "New controls ensure prompts and model outputs are processed without persistent storage.", author: "Nora Fields", initials: "NF" },
      { category: "Engineering", date: "April 5, 2026", title: "Optimizing Sandbox snapshots", excerpt: "We reduced warm-start latency for isolated code execution using layered snapshot compaction.", author: "Priya Raman", initials: "PR" },
      { category: "Customers", date: "March 29, 2026", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A customer story on adapting editorial workflows to agent-assisted publishing.", author: "Evan Liu", initials: "EL" },
      { category: "Engineering", date: "March 24, 2026", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "An inside look at coordinated optimization passes and architecture-level cache tuning.", author: "Maya Chen", initials: "MC" },
      { category: "Company News", date: "March 18, 2026", title: "Unified reporting for all AI Gateway usage", excerpt: "A single dashboard for tokens, latency, spend, and policy conformance across teams.", author: "Jules Carter", initials: "JC" },
      { category: "Community", date: "March 11, 2026", title: "Community highlights: open-source observability recipes", excerpt: "Five practical patterns from maintainers operating AI-native services at scale.", author: "Sam Okafor", initials: "SO" },
      { category: "Customers", date: "March 5, 2026", title: "From monolith to edge: migration notes from a platform team", excerpt: "How phased deployments and canary safeguards accelerated modernization.", author: "Dana Kim", initials: "DK" },
      { category: "Engineering", date: "February 28, 2026", title: "Shipping resilient retries for deployment orchestration", excerpt: "Backoff, idempotency, and replay-safe hooks for distributed delivery pipelines.", author: "Riley West", initials: "RW" },
      { category: "Company News", date: "February 20, 2026", title: "DeployCloud expands regional runtime coverage", excerpt: "New runtime regions cut tail latency for global teams and compliance workloads.", author: "Avery Patel", initials: "AP" },
      { category: "Security", date: "February 15, 2026", title: "Policy templates for regulated workloads", excerpt: "Ready-to-use security baselines for teams building in fintech and health sectors.", author: "Nora Fields", initials: "NF" },
      { category: "Community", date: "February 9, 2026", title: "Design systems for technical blogs: lessons learned", excerpt: "How to balance readability, hierarchy, and publishing velocity in docs-heavy teams.", author: "Sam Okafor", initials: "SO" }
    ];

    const PAGE_SIZE = 6;
    let activeCategory = "All Posts";
    let searchQuery = "";
    let visibleCount = PAGE_SIZE;

    const pillsEl = document.getElementById("categoryPills");
    const featuredGrid = document.getElementById("featuredGrid");
    const postsGrid = document.getElementById("postsGrid");
    const noResults = document.getElementById("noResults");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const searchInput = document.getElementById("searchInput");

    function createCard(post, featured = false) {
      const article = document.createElement("article");
      article.className = featured ? `featured-card ${post.main ? 'main' : ''}`.trim() : "post-card";
      article.innerHTML = `
        <div class="meta">
          <span class="tag">${post.category}</span>
          <span>${post.date}</span>
        </div>
        <h3>${post.title}</h3>
        <p>${post.excerpt}</p>
        ${featured && post.stats ? `<div class="stats">${post.stats.map((s) => `<div><b>${s.split(" ")[0]}</b> ${s.slice(s.indexOf(" ") + 1)}</div>`).join("")}</div>` : ""}
        <div class="author"><span class="avatar">${post.initials}</span><span>${post.author}</span></div>
      `;
      return article;
    }

    function normalize(value) {
      return value.toLowerCase().trim();
    }

    function filteredPosts() {
      return allPosts.filter((post) => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const haystack = `${post.title} ${post.excerpt} ${post.author} ${post.category}`.toLowerCase();
        const searchMatch = !searchQuery || haystack.includes(searchQuery);
        return categoryMatch && searchMatch;
      });
    }

    function renderPills() {
      pillsEl.innerHTML = "";
      categories.forEach((category) => {
        const btn = document.createElement("button");
        btn.className = `pill ${category === activeCategory ? 'active' : ''}`;
        btn.type = "button";
        btn.setAttribute("role", "tab");
        btn.setAttribute("aria-selected", String(category === activeCategory));
        btn.textContent = category;
        btn.addEventListener("click", () => {
          activeCategory = category;
          visibleCount = PAGE_SIZE;
          renderAll();
        });
        pillsEl.appendChild(btn);
      });
    }

    function renderFeatured() {
      featuredGrid.innerHTML = "";
      featuredPosts.forEach((post) => featuredGrid.appendChild(createCard(post, true)));
    }

    function renderPosts() {
      const matches = filteredPosts();
      const visible = matches.slice(0, visibleCount);
      postsGrid.innerHTML = "";
      visible.forEach((post) => postsGrid.appendChild(createCard(post)));

      noResults.style.display = matches.length ? "none" : "block";
      showMoreBtn.style.display = matches.length > visible.length ? "inline-flex" : "none";
      showMoreBtn.disabled = matches.length <= visible.length;
    }

    function renderAll() {
      renderPills();
      renderFeatured();
      renderPosts();
    }

    showMoreBtn.addEventListener("click", () => {
      visibleCount += PAGE_SIZE;
      renderPosts();
    });

    searchInput.addEventListener("input", (e) => {
      searchQuery = normalize(e.target.value);
      visibleCount = PAGE_SIZE;
      renderPosts();
    });

    const productsBtn = document.getElementById("productsBtn");
    const resourcesBtn = document.getElementById("resourcesBtn");
    const productsMenu = document.getElementById("productsMenu");
    const resourcesMenu = document.getElementById("resourcesMenu");

    function closeMenus() {
      [productsMenu, resourcesMenu].forEach((menu) => menu.classList.remove("open"));
      [productsBtn, resourcesBtn].forEach((btn) => btn.setAttribute("aria-expanded", "false"));
    }

    function toggleMenu(button, menu) {
      const isOpen = menu.classList.contains("open");
      closeMenus();
      if (!isOpen) {
        menu.classList.add("open");
        button.setAttribute("aria-expanded", "true");
      }
    }

    productsBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleMenu(productsBtn, productsMenu);
    });

    resourcesBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleMenu(resourcesBtn, resourcesMenu);
    });

    productsBtn.parentElement.addEventListener("mouseenter", () => toggleMenu(productsBtn, productsMenu));
    resourcesBtn.parentElement.addEventListener("mouseenter", () => toggleMenu(resourcesBtn, resourcesMenu));

    document.addEventListener("click", closeMenus);

    renderAll();
  </script>
</body>
</html>
EOF

