      box-shadow: var(--shadow);
      padding: 20px;
      display: none;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
    }

    .mega.open { display: grid; }

    .mega h4 {
      margin: 0 0 8px;
      font-size: 0.86rem;
      letter-spacing: .03em;
      text-transform: uppercase;
      color: #334155;
    }

    .mega ul { margin: 0; padding: 0; list-style: none; }
    .mega li { margin-bottom: 8px; color: #1f2937; font-size: .92rem; }

    .hero {
      padding: 42px 0 20px;
    }

    .hero h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 3rem);
      line-height: 1.1;
      letter-spacing: -0.02em;
    }

    .hero p {
      max-width: 720px;
      margin: 14px 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin: 24px 0 14px;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    .pill {
      border: 1px solid var(--line);
      background: #fff;
      color: #1f2937;
      border-radius: 999px;
      padding: 9px 14px;
      font-size: .9rem;
      font-weight: 600;
      cursor: pointer;
      transition: .15s ease;
      min-height: 40px;
    }

    .pill:hover { border-color: #bcd6ff; }

    .pill.active {
      background: var(--accent-soft);
      border-color: #9ec5ff;
      color: #0545a8;
    }

    .search {
      min-width: 260px;
      flex: 1;
      display: flex;
      justify-content: flex-end;
    }

    .search input {
      width: min(380px, 100%);
      border: 1px solid var(--line);
      border-radius: 12px;
      padding: 11px 14px;
      font-size: .95rem;
      outline: none;
      background: #fff;
    }

    .search input:focus { border-color: #9ec5ff; box-shadow: 0 0 0 4px #e8f2ff; }

    .section-title {
      margin: 26px 0 16px;
      font-size: 1.35rem;
      letter-spacing: -.01em;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
      margin-bottom: 24px;
    }

    .featured-card {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: #fff;
      padding: 18px;
      box-shadow: var(--shadow);
      display: flex;
      flex-direction: column;
      gap: 10px;
      min-height: 270px;
    }

    .featured-card.main {
      grid-column: span 2;
      background: linear-gradient(180deg, #ffffff, #f7fbff);
    }

    .meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      color: #475569;
      font-size: .84rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      border-radius: 999px;
      padding: 4px 10px;
      font-size: .74rem;
      font-weight: 700;
      background: var(--accent-soft);
      color: #0450be;
    }

    .featured-card h3,
    .post-card h3 {
      margin: 0;
      line-height: 1.24;
      letter-spacing: -0.01em;
    }

    .featured-card h3 { font-size: clamp(1.1rem, 2.1vw, 1.7rem); }
    .featured-card p, .post-card p { margin: 0; color: var(--muted); }

    .stats {
      margin-top: auto;
      display: grid;
      gap: 8px;
      padding-top: 8px;
      border-top: 1px dashed #bfdbfe;
    }

    .stats b { color: #0f172a; }

    .author {
      margin-top: auto;
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: .88rem;
      color: #334155;
    }

    .avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      display: inline-grid;
      place-items: center;
      font-size: .75rem;
      font-weight: 700;
      background: #e2e8f0;
      color: #0f172a;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      margin-top: 8px;
    }

    .post-card {
      border: 1px solid var(--line);
      border-radius: 12px;
      background: #fff;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      transition: transform .16s ease, box-shadow .16s ease, border-color .16s ease;
      min-height: 260px;
    }

    .post-card:hover {
      transform: translateY(-2px);
      border-color: #cddcf2;
      box-shadow: var(--shadow);
    }

    .empty {
      border: 1px dashed #cbd5e1;
      border-radius: 12px;
      padding: 24px;
      background: #fff;
      text-align: center;
      color: #475569;
      display: none;
      margin-top: 10px;
    }

    .actions {
      display: flex;
      justify-content: center;
      margin: 22px 0 8px;
    }

    .btn {
      border: 1px solid #99c0ff;
      background: #fff;
      color: #0545a8;
      font-weight: 700;
      border-radius: 10px;
      padding: 11px 16px;
      cursor: pointer;
      min-height: 44px;
    }

    .btn:hover { background: #eef5ff; }

    .cta {
      margin: 34px 0;
      border-radius: 16px;
      border: 1px solid var(--line);
      background: linear-gradient(90deg, #fff, #f4f9ff);
      padding: 22px;
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
    }

    .cta h3 { margin: 0; font-size: 1.25rem; }
    .cta p { margin: 6px 0 0; color: var(--muted); }

    .cta .btn {
      background: var(--accent);
      color: #fff;
      border-color: transparent;
    }

    footer {
      border-top: 1px solid var(--line);
      padding: 20px 0 34px;
      color: #475569;
      font-size: .92rem;
    }

    .foot-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
    }

    @media (max-width: 1000px) {
      .featured-grid,
      .posts-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .featured-card.main { grid-column: span 2; }
    }

    @media (max-width: 760px) {
      .header-inner { height: auto; padding: 12px 0; align-items: flex-start; }
      .featured-grid,
      .posts-grid { grid-template-columns: 1fr; }
      .featured-card.main { grid-column: span 1; }
      .mega { position: fixed; left: 4vw; width: 92vw; grid-template-columns: 1fr; }
      .search { width: 100%; justify-content: flex-start; }
      .search input { width: 100%; }
    }
  </style>
</head>
<body>
