  <script>
    const categories = ["All Posts", "Engineering", "Community", "Company News", "Customers", "Security"];

    const featuredPosts = [
      {
        category: "Engineering",
        date: "April 20, 2026",
        title: "Agentic Infrastructure",
        excerpt: "DeployCloud now sees a structural shift in how software ships: coding agents increasingly open, iterate, and deploy with human oversight.",
        author: "Maya Chen",
        initials: "MC",
        stats: [
          "30% of deployments are now initiated by coding agents",
          "1000% increase from six months ago",
          "Teams using agents are 20 times more likely to call AI inference"
        ],
        main: true
      },
      {
        category: "Engineering",
        date: "April 12, 2026",
        title: "A new programming model for durable execution",
        excerpt: "How resumable workflows and agent checkpoints make long-running tasks reliable in production systems.",
        author: "Leon Park",
        initials: "LP"
      },
      {
        category: "Security",
        date: "April 3, 2026",
        title: "Agent responsibly",
        excerpt: "Guardrails, approvals, and observability patterns for safe autonomous coding in high-trust organizations.",
        author: "Aria Gomez",
        initials: "AG"
      }
    ];

    const allPosts = [
      { category: "Engineering", date: "April 12, 2026", title: "A new programming model for durable execution", excerpt: "Durable execution lets workflows survive restarts, retries, and handoffs across human and agent operators.", author: "Leon Park", initials: "LP" },
      { category: "Security", date: "April 8, 2026", title: "Zero Data Retention on AI Gateway", excerpt: "New controls ensure prompts and model outputs are processed without persistent storage.", author: "Nora Fields", initials: "NF" },
      { category: "Engineering", date: "April 5, 2026", title: "Optimizing Sandbox snapshots", excerpt: "We reduced warm-start latency for isolated code execution using layered snapshot compaction.", author: "Priya Raman", initials: "PR" },
      { category: "Customers", date: "March 29, 2026", title: "How a startup made a blog platform work for humans and AI alike", excerpt: "A customer story on adapting editorial workflows to agent-assisted publishing.", author: "Evan Liu", initials: "EL" },
      { category: "Engineering", date: "March 24, 2026", title: "Making build tool 96% faster with agents, sandboxes, and humans", excerpt: "An inside look at coordinated optimization passes and architecture-level cache tuning.", author: "Maya Chen", initials: "MC" },
      { category: "Company News", date: "March 18, 2026", title: "Unified reporting for all AI Gateway usage", excerpt: "A single dashboard for tokens, latency, spend, and policy conformance across teams.", author: "Jules Carter", initials: "JC" },
      { category: "Community", date: "March 11, 2026", title: "Community highlights: open-source observability recipes", excerpt: "Five practical patterns from maintainers operating AI-native services at scale.", author: "Sam Okafor", initials: "SO" },
      { category: "Customers", date: "March 5, 2026", title: "From monolith to edge: migration notes from a platform team", excerpt: "How phased deployments and canary safeguards accelerated modernization.", author: "Dana Kim", initials: "DK" },
      { category: "Engineering", date: "February 28, 2026", title: "Shipping resilient retries for deployment orchestration", excerpt: "Backoff, idempotency, and replay-safe hooks for distributed delivery pipelines.", author: "Riley West", initials: "RW" },
      { category: "Company News", date: "February 20, 2026", title: "DeployCloud expands regional runtime coverage", excerpt: "New runtime regions cut tail latency for global teams and compliance workloads.", author: "Avery Patel", initials: "AP" },
      { category: "Security", date: "February 15, 2026", title: "Policy templates for regulated workloads", excerpt: "Ready-to-use security baselines for teams building in fintech and health sectors.", author: "Nora Fields", initials: "NF" },
      { category: "Community", date: "February 9, 2026", title: "Design systems for technical blogs: lessons learned", excerpt: "How to balance readability, hierarchy, and publishing velocity in docs-heavy teams.", author: "Sam Okafor", initials: "SO" }
    ];

    const PAGE_SIZE = 6;
    let activeCategory = "All Posts";
    let searchQuery = "";
    let visibleCount = PAGE_SIZE;

    const pillsEl = document.getElementById("categoryPills");
    const featuredGrid = document.getElementById("featuredGrid");
    const postsGrid = document.getElementById("postsGrid");
    const noResults = document.getElementById("noResults");
    const showMoreBtn = document.getElementById("showMoreBtn");
    const searchInput = document.getElementById("searchInput");

    function createCard(post, featured = false) {
      const article = document.createElement("article");
      article.className = featured ? `featured-card ${post.main ? 'main' : ''}`.trim() : "post-card";
      article.innerHTML = `
        <div class="meta">
          <span class="tag">${post.category}</span>
          <span>${post.date}</span>
        </div>
        <h3>${post.title}</h3>
        <p>${post.excerpt}</p>
        ${featured && post.stats ? `<div class="stats">${post.stats.map((s) => `<div><b>${s.split(" ")[0]}</b> ${s.slice(s.indexOf(" ") + 1)}</div>`).join("")}</div>` : ""}
        <div class="author"><span class="avatar">${post.initials}</span><span>${post.author}</span></div>
      `;
      return article;
    }

    function normalize(value) {
      return value.toLowerCase().trim();
    }

    function filteredPosts() {
      return allPosts.filter((post) => {
        const categoryMatch = activeCategory === "All Posts" || post.category === activeCategory;
        const haystack = `${post.title} ${post.excerpt} ${post.author} ${post.category}`.toLowerCase();
        const searchMatch = !searchQuery || haystack.includes(searchQuery);
        return categoryMatch && searchMatch;
      });
    }

    function renderPills() {
      pillsEl.innerHTML = "";
      categories.forEach((category) => {
        const btn = document.createElement("button");
        btn.className = `pill ${category === activeCategory ? 'active' : ''}`;
        btn.type = "button";
        btn.setAttribute("role", "tab");
        btn.setAttribute("aria-selected", String(category === activeCategory));
        btn.textContent = category;
        btn.addEventListener("click", () => {
          activeCategory = category;
          visibleCount = PAGE_SIZE;
          renderAll();
        });
        pillsEl.appendChild(btn);
      });
    }

    function renderFeatured() {
      featuredGrid.innerHTML = "";
      featuredPosts.forEach((post) => featuredGrid.appendChild(createCard(post, true)));
    }

    function renderPosts() {
      const matches = filteredPosts();
      const visible = matches.slice(0, visibleCount);
      postsGrid.innerHTML = "";
      visible.forEach((post) => postsGrid.appendChild(createCard(post)));

      noResults.style.display = matches.length ? "none" : "block";
      showMoreBtn.style.display = matches.length > visible.length ? "inline-flex" : "none";
      showMoreBtn.disabled = matches.length <= visible.length;
    }

    function renderAll() {
      renderPills();
      renderFeatured();
      renderPosts();
    }

    showMoreBtn.addEventListener("click", () => {
      visibleCount += PAGE_SIZE;
      renderPosts();
    });

    searchInput.addEventListener("input", (e) => {
      searchQuery = normalize(e.target.value);
      visibleCount = PAGE_SIZE;
      renderPosts();
    });

    const productsBtn = document.getElementById("productsBtn");
    const resourcesBtn = document.getElementById("resourcesBtn");
    const productsMenu = document.getElementById("productsMenu");
    const resourcesMenu = document.getElementById("resourcesMenu");

    function closeMenus() {
      [productsMenu, resourcesMenu].forEach((menu) => menu.classList.remove("open"));
      [productsBtn, resourcesBtn].forEach((btn) => btn.setAttribute("aria-expanded", "false"));
    }

    function toggleMenu(button, menu) {
      const isOpen = menu.classList.contains("open");
      closeMenus();
      if (!isOpen) {
        menu.classList.add("open");
        button.setAttribute("aria-expanded", "true");
      }
    }

    productsBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleMenu(productsBtn, productsMenu);
    });

    resourcesBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      toggleMenu(resourcesBtn, resourcesMenu);
    });

    productsBtn.parentElement.addEventListener("mouseenter", () => toggleMenu(productsBtn, productsMenu));
    resourcesBtn.parentElement.addEventListener("mouseenter", () => toggleMenu(resourcesBtn, resourcesMenu));

    document.addEventListener("click", closeMenus);

    renderAll();
  </script>
</body>
